/**
 * Единый, не зависящий от движка формат данных виджета.
 * Оба режима принимают одно и то же: общая шкала времени + набор рядов.
 */
export interface ChartWidgetSeries {
    id: string;
    name: string;
    /** Значения, выровненные по `timeline`; `null` — пропуск. */
    values: (number | null)[];
}

export interface ChartWidgetValueFormat {
    /** Знаков после запятой. */
    precision?: number;
    /** Единица измерения после числа: `₽`, `%`, `мс`… */
    unit?: string;
    /** Сокращать большие числа (1,2 млн). */
    compact?: boolean;
}

export interface ChartWidgetData {
    /** Unix-время в миллисекундах. */
    timeline: number[];
    series: ChartWidgetSeries[];
    valueFormat?: ChartWidgetValueFormat;
    /** Фиксированные границы оси Y (например, 0–100 для процентов). */
    yMin?: number;
    yMax?: number;
}

/**
 * Вид отображения — определяет движок:
 * - `line`  — обычный линейный график (@gravity-ui/charts, SVG);
 * - `dense` — плотный временной ряд мониторинга (Yagr/uPlot, canvas).
 */
export type ChartWidgetKind = 'line' | 'dense';

export interface ChartWidgetView<Id extends string = string> {
    id: Id;
    /** Подпись в переключателе. */
    label: string;
    kind: ChartWidgetKind;
    data: ChartWidgetData;
    /** Подзаголовок под переключателем. */
    description?: string;
}
EOF
cat > chartkit.ts <<'EOF'
import {settings} from '@gravity-ui/chartkit';
import {GravityChartsPlugin} from '@gravity-ui/chartkit/gravity-charts';
import {YagrPlugin} from '@gravity-ui/chartkit/yagr';

// Плагины лёгкие: их `renderer` — React.lazy, поэтому код движка
// (@gravity-ui/charts или Yagr/uPlot) скачивается только при первом показе
// графика соответствующего типа.
settings.set({lang: 'ru', plugins: [GravityChartsPlugin, YagrPlugin]});
EOF
cat > format.ts <<'EOF'
import type {ChartWidgetValueFormat} from './types';

export function createValueFormatter({precision = 0, unit, compact}: ChartWidgetValueFormat = {}) {
    const formatter = new Intl.NumberFormat('ru-RU', {
        maximumFractionDigits: precision,
        minimumFractionDigits: compact ? 0 : precision,
        notation: compact ? 'compact' : 'standard',
    });

    return (value: number | null | undefined) => {
        if (value === null || value === undefined || Number.isNaN(value)) {
            return '—';
        }

        const formatted = formatter.format(value);
        return unit ? `${formatted} ${unit}` : formatted;
    };
}
EOF
cat > adapters.ts <<'EOF'
// Только типы: модуль не тянет код движков в основной бандл.
import type {ChartKitWidget} from '@gravity-ui/chartkit';
import type {ChartData} from '@gravity-ui/chartkit/gravity-charts';
import type {YagrWidgetData} from '@gravity-ui/chartkit/yagr';

import {createValueFormatter} from './format';
import type {ChartWidgetData, ChartWidgetKind} from './types';

/** Аргументы для `<ChartKit />`, общий вход для обоих движков. */
export type ChartKitConfig = {
    [K in keyof ChartKitWidget]: {type: K; data: ChartKitWidget[K]['data']};
}['gravity-charts' | 'yagr'];

export type ThemeKind = 'light' | 'dark';

// Категориальная палитра: фиксированный порядок слотов, отдельные шаги для тёмной темы.
const SERIES_COLORS: Record<ThemeKind, string[]> = {
    light: ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300', '#6250d6', '#e34948'],
    dark: ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300', '#9085e9', '#e66767'],
};

const getColor = (index: number, theme: ThemeKind) => {
    const colors = SERIES_COLORS[theme];
    // Больше 8 рядов цветом не различить — такие данные нужно сворачивать в «Прочее».
    return colors[Math.min(index, colors.length - 1)];
};

function toGravityCharts(data: ChartWidgetData, theme: ThemeKind): ChartData {
    const format = createValueFormatter(data.valueFormat);
    const axisFormat = createValueFormatter({...data.valueFormat, compact: true, precision: 1});

    return {
        series: {
            data: data.series.map((series, index) => ({
                type: 'line',
                id: series.id,
                name: series.name,
                color: getColor(index, theme),
                lineWidth: 2,
                marker: {enabled: data.timeline.length <= 60, radius: 4},
                data: data.timeline.map((x, i) => ({x, y: series.values[i]})),
            })),
        },
        xAxis: {type: 'datetime'},
        yAxis: [
            {
                min: data.yMin,
                max: data.yMax,
                labels: {html: false, numberFormat: undefined},
                ...(data.valueFormat ? {labels: {numberFormat: {}}} : {}),
            },
        ],
        legend: {enabled: data.series.length > 1},
        tooltip: {
            valueFormat: {type: 'custom', formatter: ({value}) => format(Number(value))},
        },
        // Подписи оси Y — компактно (1,2 млн ₽), полные значения — в тултипе.
        ...{axisFormat},
    };
}

function toYagr(data: ChartWidgetData, theme: ThemeKind): YagrWidgetData {
    const format = createValueFormatter(data.valueFormat);
    const axisFormat = createValueFormatter({...data.valueFormat, compact: true});

    return {
        data: {
            timeline: data.timeline,
            graphs: data.series.map((series, index) => ({
                id: series.id,
                name: series.name,
                color: getColor(index, theme),
                data: series.values,
            })),
        },
        libraryConfig: {
            chart: {
                series: {type: 'line', width: 1.5, spanGaps: false},
                // Выделение мышью по оси X — зум, двойной клик — сброс.
                select: {zoom: true},
            },
            scales: {y: {min: data.yMin, max: data.yMax}},
            axes: {
                y: {values: (_u, ticks) => ticks.map((tick) => axisFormat(tick))},
            },
            cursor: {snapToValues: false},
            tooltip: {show: true, tracking: 'sticky', value: (value) => format(value as number)},
            legend: {show: data.series.length > 1, position: 'bottom'},
            processing: {nullValues: {null: null}},
        },
    };
}

export function toChartKitConfig(
    kind: ChartWidgetKind,
    data: ChartWidgetData,
    theme: ThemeKind,
): ChartKitConfig {
    switch (kind) {
        case 'line':
            return {type: 'gravity-charts', data: toGravityCharts(data, theme)};
        case 'dense':
            return {type: 'yagr', data: toYagr(data, theme)};
    }
}
EOF

